<script lang="ts">
import{onMount}from'svelte';import{api}from'../../lib/api';
type Borrower={id:number;name:string;notes:string};let borrowers:Borrower[]=[];let name='';let notes='';let error='';let message='';let busy=false;let key='';let payload='';let editing:Borrower|null=null;let editName='';let editNotes='';
async function load(){try{borrowers=await api<Borrower[]>('/api/borrowers');}catch(e){error=(e as Error).message;}}
onMount(()=>{load();});
async function add(){busy=true;error='';const next=JSON.stringify([name.trim(),notes.trim()]);if(payload!==next){payload=next;key=crypto.randomUUID();}try{await api('/api/borrowers',{name:name.trim(),notes:notes.trim(),request_key:key});name='';notes='';payload='';await load();message='Borrower added.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
function startEdit(b:Borrower){editing=b;editName=b.name;editNotes=b.notes;}
async function saveEdit(){if(!editing)return;busy=true;error='';try{await api(`/api/borrowers/${editing.id}`,{name:editName,notes:editNotes,expected_name:editing.name,expected_notes:editing.notes},'PATCH');editing=null;await load();message='Borrower updated.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
async function archive(id:number){busy=true;error='';try{await api(`/api/borrowers/${id}/archive`,{});await load();message='Borrower archived. Their loan history is preserved.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<div class="borrowers_wrap">{#if error}<p role="alert" class="library-error">{error}</p>{/if}<form class="borrowers_form" onsubmit={(e)=>{e.preventDefault();add();}}><label class="library-field">Borrower name<input bind:value={name} maxlength="200" required disabled={busy}/></label><label class="library-field">Notes (optional)<input bind:value={notes} maxlength="2000" disabled={busy}/></label><button class="library-button" disabled={busy}>Add borrower</button></form><p class="library-help">Archive people you no longer lend to. Their history stays in your library; books must be returned first.</p>{#each borrowers as b}<article class="borrower_row"><div><strong>{b.name}</strong>{#if b.notes}<p>{b.notes}</p>{/if}</div><div class="library-actions"><button class="library-button secondary" disabled={busy} onclick={()=>startEdit(b)}>Edit</button><button class="library-button secondary" disabled={busy} onclick={()=>archive(b.id)}>Archive</button></div></article>{/each}{#if editing}<form class="borrowers_form" onsubmit={(e)=>{e.preventDefault();saveEdit();}}><label class="library-field">Edit borrower name<input bind:value={editName} maxlength="200" required disabled={busy}/></label><label class="library-field">Edit notes<input bind:value={editNotes} maxlength="2000" disabled={busy}/></label><button class="library-button" disabled={busy}>Save changes</button><button type="button" class="library-button secondary" disabled={busy} onclick={()=>editing=null}>Cancel</button></form>{/if}{#if !borrowers.length}<p>No borrowers yet.</p>{/if}<p role="status">{message}</p></div>
<style>@layer components{.borrowers_wrap{display:grid;gap:var(--space-4)}.borrowers_form{display:flex;flex-wrap:wrap;align-items:end;gap:var(--space-3);label{flex:1;min-width:12rem}}.borrower_row{display:flex;align-items:center;justify-content:space-between;gap:var(--space-3);padding:var(--space-4);border:var(--border-width) solid var(--border);border-radius:var(--radius-main);background:var(--background-3)}} </style>
